package app.dayflow;
import android.widget.*;import org.json.*;
/** Existing copies are never silently deleted; the user explicitly chooses a resolution. */
final class SyncConflicts {static void show(MainActivity a,int offset){LinearLayout page=a.fullPage("同步冲突",a::home);page.addView(Ui.help(a,"正常先后修改按修订关系合并；真正并发或历史不足的修改保留副本。旧副本不会自动清除，请比较后选择。"));try{JSONArray rows=Data.get(a).conflictsPage(offset);for(int i=0;i<rows.length();i++){JSONObject copy=rows.getJSONObject(i);page.addView(Ui.button(a,copy.optString("title"),false,()->compare(a,copy.optString("id"))));}if(rows.length()==0)page.addView(Ui.help(a,"暂无待处理冲突"));if(offset>0)page.addView(Ui.button(a,"上一页",false,()->show(a,Math.max(0,offset-30))));if(rows.length()==30)page.addView(Ui.button(a,"下一页",false,()->show(a,offset+30)));}catch(Exception e){a.message(e.getMessage());}}
 private static void compare(MainActivity a,String id){try{JSONObject copy=Data.get(a).find(id);if(copy==null)throw new Exception("副本已不存在");JSONObject original=Data.get(a).find(copy.optString("conflict_of"));LinearLayout page=a.fullPage("比较冲突内容",()->show(a,0));page.addView(Ui.text(a,"当前原记录",20,true));page.addView(Ui.text(a,original==null?"原记录不存在":summary(original),15,false));page.addView(Ui.text(a,"保留的本地副本",20,true));page.addView(Ui.text(a,summary(copy),15,false));page.addView(Ui.help(a,"这里只摘要显示正文，完整内容可进入编辑器查看。每次处理都会再次核对修订；处理结果随记录同步。"));page.addView(Ui.button(a,"查看副本全文",false,()->a.detail(copy)));for(String[] option:new String[][]{{"local","用副本内容更新原记录"},{"remote","保留当前原记录，删除副本"},{"both","两份都保留，标记已处理"}})page.addView(Ui.button(a,option[1],false,()->a.job(()->{Data.get(a).settleConflict(id,copy.optString("revision"),original==null?"":original.optString("revision"),option[0]);return "已处理冲突";},()->show(a,0))));}catch(Exception e){a.message(e.getMessage());}}
 private static String summary(JSONObject r){String content=r.optString("content");return r.optString("title")+"\n"+PlanTime.label(r)+"\n"+(r.optBoolean("deleted")?"已删除\n":"")+content.substring(0,Math.min(2000,content.length()));}}
